using Nro.Data.Db;
using Nro.Data.Repositories.Gift;
using Nro.Tests.Integration.Db;

namespace Nro.Tests.Integration.Inv;

/// <summary>The three gift-code statements on a real PostgreSQL (database <c>nro_test</c>, synthetic rows only, the table shapes copied from <c>postgres/schema/schema.sql</c>).</summary>
public sealed class GiftCodeFixture : TestDatabase
{
    protected override async Task SeedAsync()
    {
        await RunAsync(
            "create table gift_code(id integer generated by default as identity primary key, code citext not null, item text not null default '', option text not null default '', "
            + "list_id_players text not null default '', created_at text not null default '', expired text not null default '', count_left integer not null default 100)");
        await RunAsync("create table gift_code_redemption(id integer not null, player_id integer, redeemed_code varchar(255), redeemed_at timestamp)");
    }

    public Task ResetAsync() => RunAsync("truncate table gift_code, gift_code_redemption restart identity");
}

public class GiftCodeRepositoryTests : IClassFixture<GiftCodeFixture>, IAsyncLifetime
{
    private readonly GiftCodeFixture fixture;

    public GiftCodeRepositoryTests(GiftCodeFixture fixture)
    {
        this.fixture = fixture;
    }

    private GiftCodeRepository Repo => new(fixture.Db);

    public Task InitializeAsync() => fixture.ResetAsync();

    public Task DisposeAsync() => Task.CompletedTask;

    private Task Insert(string code, int countLeft) => fixture.Db.ExecuteUpdateAsync("insert into gift_code(code, count_left) values (?, ?)", code, countLeft);

    [Fact]
    public async Task GetCountLeft_reads_the_count_of_the_row_and_ignores_case()
    {
        await Insert("Tet2026", 42);

        Assert.Equal(42, await Repo.GetCountLeftAsync("Tet2026"));
        Assert.Equal(42, await Repo.GetCountLeftAsync("TET2026"));
    }

    [Fact]
    public async Task GetCountLeft_is_null_for_an_unknown_code()
    {
        await Insert("Tet2026", 42);

        Assert.Null(await Repo.GetCountLeftAsync("other"));
        Assert.Null(await Repo.GetCountLeftAsync(string.Empty));
    }

    [Theory]
    [InlineData(0)]
    [InlineData(-5)]
    [InlineData(int.MaxValue)]
    public async Task GetCountLeft_returns_boundary_values_unchanged(int count)
    {
        await Insert("edge", count);
        Assert.Equal(count, await Repo.GetCountLeftAsync("edge"));
    }

    [Fact]
    public async Task GetCountLeft_uses_the_lowest_id_when_a_code_appears_twice()
    {
        await Insert("dup", 1);
        await Insert("dup", 2);

        Assert.Equal(1, await Repo.GetCountLeftAsync("dup"));
    }

    [Fact]
    public async Task SetCountLeft_changes_one_row_only()
    {
        await Insert("a", 10);
        await Insert("b", 20);

        int changed = await Repo.SetCountLeftAsync("a", 9);

        Assert.Equal(1, changed);
        Assert.Equal(9, await Repo.GetCountLeftAsync("a"));
        Assert.Equal(20, await Repo.GetCountLeftAsync("b"));
    }

    [Fact]
    public async Task SetCountLeft_with_a_duplicate_code_updates_only_the_lowest_id()
    {
        await Insert("dup", 1);
        await Insert("dup", 2);

        Assert.Equal(1, await Repo.SetCountLeftAsync("dup", 77));

        Assert.Equal(77, await fixture.ScalarAsync<int>("select count_left from gift_code where id = 1"));
        Assert.Equal(2, await fixture.ScalarAsync<int>("select count_left from gift_code where id = 2"));
    }

    [Fact]
    public async Task SetCountLeft_for_an_unknown_code_changes_nothing()
    {
        await Insert("a", 10);

        Assert.Equal(0, await Repo.SetCountLeftAsync("zzz", 1));
        Assert.Equal(10, await Repo.GetCountLeftAsync("a"));
    }

    [Fact]
    public async Task SaveUse_inserts_the_row_and_keeps_the_wall_clock_time_exactly()
    {
        await Repo.SaveUseAsync(4242, 99, "Tet2026", new DateTime(2026, 11, 3, 10, 30, 15));

        Assert.Equal(1L, await fixture.ScalarAsync<long>("select count(*) from gift_code_redemption"));
        Assert.Equal(4242, await fixture.ScalarAsync<int>("select id from gift_code_redemption"));
        Assert.Equal(99, await fixture.ScalarAsync<int>("select player_id from gift_code_redemption"));
        Assert.Equal("Tet2026", await fixture.ScalarAsync<string>("select redeemed_code from gift_code_redemption"));
        Assert.Equal("2026-11-03 10:30:15", await fixture.ScalarAsync<string>("select to_char(redeemed_at, 'YYYY-MM-DD HH24:MI:SS') from gift_code_redemption"));
    }

    [Theory]
    [InlineData(DateTimeKind.Utc)]
    [InlineData(DateTimeKind.Local)]
    [InlineData(DateTimeKind.Unspecified)]
    public async Task SaveUse_ignores_the_kind_of_the_date_so_no_zone_conversion_happens(DateTimeKind kind)
    {
        await Repo.SaveUseAsync(1, 2, "x", new DateTime(2026, 1, 1, 0, 0, 0, kind));

        Assert.Equal("2026-01-01 00:00:00", await fixture.ScalarAsync<string>("select to_char(redeemed_at, 'YYYY-MM-DD HH24:MI:SS') from gift_code_redemption"));
    }

    [Fact]
    public async Task SaveUse_accepts_a_player_id_above_32_bits_only_if_the_column_can_hold_it()
    {
        await Assert.ThrowsAnyAsync<Exception>(() => Repo.SaveUseAsync(1, 3_000_000_000L, "x", DateTime.UnixEpoch));
        Assert.Equal(0L, await fixture.ScalarAsync<long>("select count(*) from gift_code_redemption"));
    }

    [Theory]
    [InlineData("x'; drop table gift_code; --")]
    [InlineData("' or '1'='1")]
    [InlineData("a\\'b")]
    [InlineData("ngọc rồng")]
    public async Task A_hostile_code_is_just_a_value(string code)
    {
        await Insert("real", 5);

        Assert.Null(await Repo.GetCountLeftAsync(code));
        Assert.Equal(0, await Repo.SetCountLeftAsync(code, 1));
        await Repo.SaveUseAsync(1, 2, code, DateTime.UnixEpoch);

        Assert.Equal(5, await Repo.GetCountLeftAsync("real"));
        Assert.Equal(code, await fixture.ScalarAsync<string>("select redeemed_code from gift_code_redemption"));
        Assert.Equal(1L, await fixture.ScalarAsync<long>("select count(*) from gift_code"));
    }

    [Fact]
    public async Task Null_code_is_rejected()
    {
        await Assert.ThrowsAsync<ArgumentNullException>(() => Repo.GetCountLeftAsync(null!));
        await Assert.ThrowsAsync<ArgumentNullException>(() => Repo.SetCountLeftAsync(null!, 1));
        await Assert.ThrowsAsync<ArgumentNullException>(() => Repo.SaveUseAsync(1, 1, null!, DateTime.UnixEpoch));
        Assert.Throws<ArgumentNullException>(() => new GiftCodeRepository(null!));
    }
}
